  let stRunning=false;
  function stRun(){if(stRunning)return;const box=document.getElementById("st-comp"),ov=document.getElementById("st-overall"),sum=document.getElementById("st-sum"),when=document.getElementById("st-when");if(!box)return;stRunning=true;
    box.innerHTML=PROBES.map((c,i)=>`<div class="probe"><div><span class="nm">${esc(c.name)}</span> <span class="dt">· ${esc(c.detail)}</span><div class="dt" id="pb-t${i}">Not checked yet</div></div><span class="st" id="pb-s${i}" data-state="checking">Checking…</span></div>`).join("");
    ov.dataset.state="checking";sum.textContent="Checking…";when.textContent="Contacting each service from this browser.";
    const done=results=>{stRunning=false;const t=new Date().toLocaleTimeString();
      results.forEach((ok,i)=>{const s=document.getElementById("pb-s"+i);s.dataset.state=ok?"up":"down";s.textContent=ok?"Up":"Not reachable from this browser";document.getElementById("pb-t"+i).textContent="Checked at "+t});
      const up=results.filter(Boolean).length;
      if(up===results.length){ov.dataset.state="up";sum.textContent="Everything this page checks is up."}
      else if(up===0){ov.dataset.state="down";sum.textContent="Nothing could be reached from this browser."}
      else{ov.dataset.state="partial";sum.textContent="Part of Semester could not be reached from this browser."}
      when.textContent=`Checked at ${t} from this browser. “Up” means it answered just now; it is not an uptime figure.`};
    if(navigator.onLine===false){done(PROBES.map(()=>false));sum.textContent="Your device is offline, so nothing could be checked.";return}
    Promise.all(PROBES.map(probe)).then(done,()=>done(PROBES.map(()=>false)))}
